/// The block of `role` of capture `capture` (nullptr: none).
inline const Block* find(uint16_t capture, const char* role) {
    for (const Block& b : kBlocks) {
        if (b.capture == capture && std::strcmp(b.role, role) == 0) return &b;
    }
    return nullptr;
}

